function highlightReply(id) {
	if (typeof window.event != "undefined" && event.which == 2) {
		// don't highlight on middle click
		return true;
	}

	let divs = document.getElementsByTagName('div');
	for (let i = 0; i < divs.length; i++) {
		if (divs[i].className.indexOf('post') != -1) {
			divs[i].className = divs[i].className.replace(/highlighted/, '');
		}
	}
	if (id) {
		let post = document.getElementById('reply_' + id);
		if (post) {
			post.className += ' highlighted';
		}
		window.location.hash = id;
	}
	return true;
}

function generatePassword() {
	let pass = '';
	let chars = '{% endverbatim %}{{ config.genpassword_chars }}{% verbatim %}';
	for (let i = 0; i < 8; i++) {
		let rnd = Math.floor(Math.random() * chars.length);
		pass += chars.substring(rnd, rnd + 1);
	}
	return pass;
}

function doPost(form) {
	if (form.elements['name']) {
		localStorage.name = form.elements['name'].value.replace(/( |^)## .+$/, '');
	}
	if (form.elements['password']) {
		localStorage.password = form.elements['password'].value;
	}
	if (form.elements['email'] && form.elements['email'].value != 'sage') {
		localStorage.email = form.elements['email'].value;
	}

	saved[document.location] = form.elements['body'].value;
	sessionStorage.body = JSON.stringify(saved);

	return form.elements['body'].value != "" || (form.elements['file'] && form.elements['file'].value != "") || (form.elements.file_url && form.elements['file_url'].value != "");
}

function citeReply(id, with_link) {
	let textarea = document.getElementById('body');
	if (!textarea) {
		return false;
	}

	if (textarea.selectionStart || textarea.selectionStart == '0') {
		let start = textarea.selectionStart;
		let end = textarea.selectionEnd;
		textarea.value = textarea.value.substring(0, start) + '>>' + id + '\n' + textarea.value.substring(end, textarea.value.length);

		textarea.selectionStart += ('>>' + id).length + 1;
		textarea.selectionEnd = textarea.selectionStart;
	} else {
		// ???
		textarea.value += '>>' + id + '\n';
	}
	if (typeof $ != 'undefined') {
		let select = document.getSelection().toString();
		if (select) {
			let body = $('#reply_' + id + ', #op_' + id).find('div.body');  // TODO: support for OPs
			let index = body.text().indexOf(select.replace('\n', ''));  // for some reason this only works like this
			if (index > -1) {
				textarea.value += '>' + select + '\n';
			}
		}

		$(window).trigger('cite', [id, with_link]);
		$(textarea).change();
	}
	return false;
}

function rememberStuff() {
	if (document.forms.post) {
		if (document.forms.post.password) {
			if (!localStorage.password) {
				localStorage.password = generatePassword();
			}
			document.forms.post.password.value = localStorage.password;
		}

		if (localStorage.name && document.forms.post.elements['name']) {
			document.forms.post.elements['name'].value = localStorage.name;
		}
		if (localStorage.email && document.forms.post.elements['email']) {
			document.forms.post.elements['email'].value = localStorage.email;
		}

		if (window.location.hash.indexOf('q') == 1) {
			citeReply(window.location.hash.substring(2), true);
		}

		if (sessionStorage.body) {
			let saved = JSON.parse(sessionStorage.body);
			if (getCookie('{% endverbatim %}{{ config.cookies.js }}{% verbatim %}')) {
				// Remove successful posts
				let successful = JSON.parse(getCookie('{% endverbatim %}{{ config.cookies.js }}{% verbatim %}'));
				for (let url in successful) {
					saved[url] = null;
				}
				sessionStorage.body = JSON.stringify(saved);

				document.cookie = '{% endverbatim %}{{ config.cookies.js }}{% verbatim %}={};expires=0;path=/;';
			}
			if (saved[document.location]) {
				document.forms.post.body.value = saved[document.location];
			}
		}

		if (localStorage.body) {
			document.forms.post.body.value = localStorage.body;
			localStorage.body = '';
		}
	}
}

var script_settings = function(script_name) {
	this.script_name = script_name;
	this.get = function(var_name, default_val) {
		if (typeof tb_settings == 'undefined' ||
			typeof tb_settings[this.script_name] == 'undefined' ||
			typeof tb_settings[this.script_name][var_name] == 'undefined') {
			return default_val;
		}
		return tb_settings[this.script_name][var_name];
	}
};

function initPostFormModal() {
	var overlay = document.getElementById('post-form-overlay');
	if (!overlay || overlay.dataset.modalInit === '1') {
		return;
	}
	overlay.dataset.modalInit = '1';

	var btn = document.getElementById('show-post-form-btn');
	var isMouseDownOnOverlay = false;

	function openModal() {
		overlay.classList.add('visible');
		overlay.style.display = 'flex';
		document.body.style.overflow = 'hidden';
		var postForm = document.forms['post'];
		if (postForm) {
			if (typeof initStylingToolbar === 'function') initStylingToolbar();
			if (typeof initKaomojiToolbar === 'function') initKaomojiToolbar();
			if (typeof initCharCounters === 'function') initCharCounters();
			if (typeof initFileUpload === 'function') initFileUpload();
			if (postForm.elements['body'] && typeof updateCharCounter === 'function') {
				updateCharCounter(postForm.elements['body']);
			}
			if (postForm.elements['subject'] && !postForm.elements['subject'].value) {
				postForm.elements['subject'].focus();
			} else if (postForm.elements['body']) {
				postForm.elements['body'].focus();
			}
		}
	}

	function closeModal() {
		overlay.classList.remove('visible');
		overlay.style.display = 'none';
		document.body.style.overflow = '';
	}

	if (btn) {
		btn.addEventListener('click', function(e) {
			e.preventDefault();
			openModal();
		});
	}

	overlay.addEventListener('mousedown', function(e) {
		isMouseDownOnOverlay = (e.target === overlay);
	});

	overlay.addEventListener('click', function(e) {
		if (e.target === overlay && isMouseDownOnOverlay) {
			closeModal();
		}
		isMouseDownOnOverlay = false;
	});

	document.addEventListener('keydown', function(e) {
		if (e.key === 'Escape' || e.keyCode === 27) {
			if (overlay.classList.contains('visible') || overlay.style.display === 'flex') {
				closeModal();
			}
		}
	});

	if (typeof $ !== 'undefined') {
		$(window).on('cite', function() {
			openModal();
		});
	}

	if (window.location.hash === '#postform' || window.location.hash === '#reply') {
		openModal();
	}

	window.openPostFormModal = openModal;
	window.closePostFormModal = closeModal;
}

function scrollToReplyForm(e) {
	if (e && e.preventDefault) e.preventDefault();
	var postForm = document.forms['post'] || document.querySelector('form[name="post"]');
	if (postForm) {
		var smooth = (typeof getVichanOption === 'function') ? getVichanOption('smooth_scrolling', true) : true;
		postForm.scrollIntoView({ behavior: smooth ? 'smooth' : 'auto' });
		var comment = postForm.elements['body'] || postForm.elements['name'];
		if (comment) {
			try {
				comment.focus({ preventScroll: true });
			} catch (err) {
				comment.focus();
			}
		}
	}
}
window.scrollToReplyForm = scrollToReplyForm;

function initReplyScrollButton() {
	var btn = document.getElementById('scroll-to-reply-btn');
	if (!btn || btn.dataset.scrollInit === '1') {
		return;
	}
	btn.dataset.scrollInit = '1';

	btn.addEventListener('click', scrollToReplyForm);
}

function replaceTextareaRange(textarea, text, start, end, selectMode) {
	if (typeof textarea.setRangeText === 'function') {
		textarea.setRangeText(text, start, end, selectMode);
	} else {
		textarea.value = textarea.value.substring(0, start) + text + textarea.value.substring(end);
		if (selectMode === 'select') {
			textarea.selectionStart = start;
			textarea.selectionEnd = start + text.length;
		} else {
			textarea.selectionStart = textarea.selectionEnd = start + text.length;
		}
	}
}

function applyCommentStyling(type, textarea) {
	if (!textarea) textarea = document.getElementById('body');
	if (!textarea) return;

	var start = textarea.selectionStart;
	var end = textarea.selectionEnd;
	var value = textarea.value;
	var selectedText = value.substring(start, end);

	var prefix = '', suffix = '';

	if (type === 'bold') {
		prefix = '[b]'; suffix = '[/b]';
	} else if (type === 'italics') {
		prefix = '[i]'; suffix = '[/i]';
	} else if (type === 'spoiler') {
		prefix = '[spoiler]'; suffix = '[/spoiler]';
	} else if (/^size-[1-6]$/.test(type)) {
		var s = type.charAt(5);
		prefix = '[s' + s + ']'; suffix = '[/s' + s + ']';
	} else if (type === 'ascii' || type === 'kao') {
		prefix = '[kao]'; suffix = '[/kao]';
	} else {
		return;
	}

	textarea.focus();

	if (selectedText.length > 0) {
		replaceTextareaRange(textarea, prefix + selectedText + suffix, start, end, 'select');
	} else {
		replaceTextareaRange(textarea, prefix + suffix, start, end, 'end');
		var newCursor = start + prefix.length;
		textarea.setSelectionRange(newCursor, newCursor);
	}

	textarea.dispatchEvent(new Event('input', { bubbles: true }));
}

window.applyCommentStyling = applyCommentStyling;

function toggleStylingMenu(toggle, e) {
	if (e) {
		if (e._stylingHandled) return;
		e._stylingHandled = true;
		if (e.preventDefault) e.preventDefault();
	}
	if (!toggle) return;
	var toolbar = toggle.closest ? toggle.closest('.styling-toolbar') : toggle.parentElement;
	if (!toolbar) return;
	var menu = toolbar.querySelector('.styling-menu');
	if (!menu) return;

	var isHidden = (menu.style.display === 'none' || !menu.classList.contains('open'));
	if (isHidden) {
		menu.style.display = 'flex';
		menu.classList.add('open');
		toggle.textContent = '▼ Styling';
	} else {
		menu.style.display = 'none';
		menu.classList.remove('open');
		toggle.textContent = '▶ Styling';
	}
}
window.toggleStylingMenu = toggleStylingMenu;

function toggleKaomojiMenu(toggle, e) {
	if (e) {
		if (e._kaomojiHandled) return;
		e._kaomojiHandled = true;
		if (e.preventDefault) e.preventDefault();
	}
	if (!toggle) return;
	var toolbar = toggle.closest ? toggle.closest('.kaomoji-toolbar') : toggle.parentElement;
	if (!toolbar) return;
	var menu = toolbar.querySelector('.kaomoji-menu');
	if (!menu) return;

	var isHidden = (menu.style.display === 'none' || !menu.classList.contains('open'));
	if (isHidden) {
		menu.style.display = 'flex';
		menu.classList.add('open');
		toggle.textContent = '▼ Kaomoji';
	} else {
		menu.style.display = 'none';
		menu.classList.remove('open');
		toggle.textContent = '▶ Kaomoji';
	}
}
window.toggleKaomojiMenu = toggleKaomojiMenu;

function initStylingToolbar() {
	var toolbars = document.querySelectorAll('.styling-toolbar');
	for (var t = 0; t < toolbars.length; t++) {
		var toolbar = toolbars[t];
		if (toolbar.dataset.stylingInit === '1') continue;
		toolbar.dataset.stylingInit = '1';

		(function(tb) {
			var toggle = tb.querySelector('.styling-toggle');
			if (toggle) {
				toggle.addEventListener('click', function(e) {
					toggleStylingMenu(toggle, e);
				});
				toggle.addEventListener('keydown', function(e) {
					if (e.key === 'Enter' || e.key === ' ') {
						toggleStylingMenu(toggle, e);
					}
				});
			}

			var menu = tb.querySelector('.styling-menu');
			if (menu) {
				menu.addEventListener('click', function(e) {
					var btn = e.target.closest ? e.target.closest('.styling-btn') : null;
					if (!btn) return;
					if (e._stylingBtnHandled) return;
					e._stylingBtnHandled = true;
					e.preventDefault();
					var style = btn.getAttribute('data-style');
					if (style) {
						var form = tb.closest ? tb.closest('form') : null;
						var textarea = form ? form.querySelector('textarea[name="body"]') : document.getElementById('body');
						applyCommentStyling(style, textarea);
					}
				});
			}
		})(toolbar);
	}
}
